def can_partition_sequence(n, a):
    if n == 1:
        return "YES", [0]

    increasing = []
    decreasing = []

    for i in range(n):
        if not increasing or a[i] > increasing[-1]:
            increasing.append(a[i])
        elif not decreasing or a[i] < decreasing[-1]:
            decreasing.append(a[i])
        else:
            return "NO", []

    # Check if we can form the original sequence by combining increasing and decreasing
    combined = []
    i, j = 0, 0
    while i < len(increasing) and j < len(decreasing):
        if increasing[i] <= decreasing[j]:
            combined.append(increasing[i])
            i += 1
        else:
            combined.append(decreasing[j])
            j += 1

    while i < len(increasing):
        combined.append(increasing[i])
        i += 1

    while j < len(decreasing):
        combined.append(decreasing[j])
        j += 1

    if combined == a:
        res = [0] * len(increasing) + [1] * len(decreasing)
        return "YES", res
    else:
        return "NO", []

